using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatClientBuilder => chatClientBuilder
    .UseLogging()
    .UseFunctionInvocation()
    .UseOpenAIChatClient(
        builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18",
        new OpenAIClient(
            builder.Configuration["AI:ApiKey"]
                ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
                ?? throw new InvalidOperationException(
                    "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable."))));

builder.Services.AddSingleton<ResearchTools>();
builder.Logging.SetMinimumLevel(LogLevel.Warning);

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 2048,
            Tools = [
                AIFunctionFactory.Create(researchTools.SearchWeb),
                AIFunctionFactory.Create(researchTools.SaveNote),
                AIFunctionFactory.Create(researchTools.GetNotes),
            ],
        },
    },
    instructions: """
        You are a research assistant. When given a topic, you:
        1. Search the web for relevant information using multiple queries.
        2. Save important findings as notes with descriptive titles.
        3. After gathering enough information, retrieve all notes and produce a comprehensive summary.
        Always cite your sources. Be thorough but concise.
        """);

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the impact of artificial intelligence on healthcare in 2025";

Console.WriteLine($"🔬 Researching: {topic}\n");

var session = new AgentSession();
var response = await agent.RunAsync($"Research the following topic and provide a summary: {topic}", session);

Console.WriteLine(response.Text);
Console.WriteLine($"\n📝 Notes collected: {researchTools.NoteCount}");

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
sealed class ResearchTools
{
    private readonly List<(string Title, string Content)> _notes = [];
    private readonly HttpClient _httpClient = new();

    public int NoteCount => _notes.Count;

    [Description("Search the web for information on a given query. Returns relevant search results.")]
    public async Task<string> SearchWeb(
        [Description("The search query to look up")] string query)
    {
        try
        {
            // Uses a simple web search API; replace with your preferred search provider
            var encoded = Uri.EscapeDataString(query);
            var response = await _httpClient.GetStringAsync(
                $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1");

            if (string.IsNullOrWhiteSpace(response) || response.Length < 20)
            {
                return $"No results found for: {query}. Try a different search query.";
            }

            return $"Search results for '{query}':\n{response[..Math.Min(response.Length, 3000)]}";
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}. Try again with a different query.";
        }
    }

    [Description("Save a research note with a title and content for later reference.")]
    public string SaveNote(
        [Description("A short descriptive title for the note")] string title,
        [Description("The content of the note including key findings and source URLs")] string content)
    {
        _notes.Add((title, content));
        return $"Note saved: '{title}' (total notes: {_notes.Count})";
    }

    [Description("Retrieve all saved research notes to compile a summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet. Use SearchWeb to find information first.";
        }

        var result = string.Join("\n\n", _notes.Select((n, i) =>
            $"--- Note {i + 1}: {n.Title} ---\n{n.Content}"));

        return result;
    }
}

